// Standard Forward: Range-based (OBO safe default)
std::vector<int> v;
for (const auto& item : v) {
    // Avoids index boundary management
}

// Standard Forward: Index-based (OBO risk mitigation)
// Start i=0, loop while i < size()
for (size_t i = 0; i < v.size(); ++i) {
    v[i] = 0;
}

// Backward Iteration: Avoid unsigned underflow
// Use signed int for index i, check against i >= 0
for (int i = v.size() - 1; i >= 0; --i) {
    // If v.size() is 0, (0-1) == -1, loop skips safely
}

// Iterator check: Boundary is != end(), not < end()
for (auto it = v.begin(); it != v.end(); ++it) {
    // ...
}

// Iterator check: Reversing safe iterator access
for (auto it = v.rbegin(); it != v.rend(); ++it) {
    // ...
}
